    def digit_sum(n):
        digits = str(n)
        total = 0
        for i, d in enumerate(digits):
            if i == 0 and d == '-':
                total -= int(digits[i+1])
            elif d.isdigit():
                total += int(d)
        return total

    return sum(1 for x in arr if digit_sum(x) > 0)
